    def test_rehashed_missing_source_unit_packet_and_pin_mutations_reject_then_restore(self):
        document=json.loads(Path(os.environ['LIGHT_SEQUENCE_NUMERIC_AFTER190_RECEIPT']).read_text());cohort.reconcile(document)
